  postIntro: "Describe what happened in your own words — for free. Lawyers in the relevant field see the case without your full name; the conflict-of-interest check runs automatically. When a lawyer accepts your case you are notified by email and continue the conversation here.",
  myCaseIntroT: "My case — how to follow it",
  myCaseIntro: "Sign in with your email to see your case status, messages with your lawyer and documents. The SOS button is for urgent situations — your description goes instantly to on-duty lawyers and the first to take it contacts you.",
  lawyersIntroT: "The lawyer directory",
  lawyersIntro: "Every lawyer here is registered on the platform. Filter by practice area, city and language — then send your case directly to the lawyer you choose, or post it for everyone.",
