  // Per-page intros / how-it-works
  introShow: "Kako funkcionira ova stranica?",
  introHide: "Razumijem",
  avaIntroT: "Kako koristiti Avu",
  avaIntro: "Napišite pitanje na svom jeziku — Ava odgovara besplatno, citirajući relevantni član zakona Kosova. Ovo je pravna informacija, ne pravni savjet: za vaš konkretan slučaj, objavite ga i licencirani advokat će vas kontaktirati.",
  postIntroT: "Kako funkcionira objavljivanje slučaja",
  postIntro: "Opišite šta se dogodilo svojim riječima — besplatno. Advokati iz odgovarajuće oblasti vide slučaj bez vašeg punog imena; provjera sukoba interesa vrši se automatski. Kada advokat prihvati vaš slučaj, dobijate obavijest e-poštom i nastavljate razgovor ovdje.",
  myCaseIntroT: "Moj slučaj — kako ga pratiti",
  myCaseIntro: "Prijavite se svojom e-poštom da vidite status slučaja, poruke s advokatom i dokumente. SOS dugme je za hitne situacije — opis odmah stiže dežurnim advokatima i prvi koji ga preuzme vas kontaktira.",
  lawyersIntroT: "Imenik advokata",
  lawyersIntro: "Svaki advokat ovdje je registriran na platformi. Filtrirajte po oblasti, gradu i jeziku — zatim pošaljite slučaj direktno advokatu kojeg izaberete, ili ga objavite za sve.",
  dashIntroT: "Panel — vaš dan na prvi pogled",
  dashIntro: "Vidite najbliže rokove, ročišta ove sedmice, aktivne predmete i otvorene zadatke. Počnite dan ovdje: sve što danas traži pažnju prikazano je na vrhu.",
  intakeIntroT: "Prijem — od zahtjeva do predmeta",
  intakeIntro: "Svaki novi klijent počinje ovdje: unesite stranke i opis, sistem automatski provjerava sukob interesa, a jednim klikom zahtjev postaje predmet s kompletnim dosjeom.",
  mattersIntroT: "Predmeti — digitalni dosje",
  mattersIntro: "Svaki predmet sadrži stranke, rokove izračunate automatski po LPK/KPPRK/LKA, šifrirane dokumente, bilješke, zadatke i radne sate. Otvorite predmet da vidite sve na jednom mjestu.",
  contactsIntroT: "Kontakti — stranke i klijenti",
  contactsIntro: "Registar lica i firmi: klijenti, suprotne stranke, sudovi. Odavde klijentima dajete pristup njihovom portalu i upravljate saglasnostima o privatnosti (Zakon 06/L-082).",
  calendarIntroT: "Kalendar — rokovi i ročišta",
  calendarIntro: "Svi rokovi i ročišta vaših predmeta na jednom mjestu. Zakonski rokovi se računaju automatski sa zvaničnim praznicima Kosova — podsjetnici e-poštom stižu prije isteka.",
  templatesIntroT: "Šabloni — podnesci za sekunde",
